package kr.payloadrunner;
import burp.*;
import kr.payloadrunner.*;import java.lang.reflect.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.atomic.*;import javax.swing.*;
public final class ExtenderTest {
 static Object defaultValue(Method m){Class<?> c=m.getReturnType();if(c==boolean.class)return false;if(c==int.class)return 0;if(c==byte.class)return (byte)0;return null;}
 static <T>T proxy(Class<T> c,InvocationHandler h){return c.cast(java.lang.reflect.Proxy.newProxyInstance(c.getClassLoader(),new Class[]{c},h));}
 public static void run(int port)throws Exception{
  AtomicInteger scopeChecks=new AtomicInteger(),sendCount=new AtomicInteger(),repeat=new AtomicInteger();AtomicBoolean tab=new AtomicBoolean();
  IExtensionHelpers helpers=proxy(IExtensionHelpers.class,(p,m,a)->{if(m.getName().equals("buildHttpService")){String host=(String)a[0];int po=(Integer)a[1];boolean ssl=(Boolean)a[2];return proxy(IHttpService.class,(p2,m2,a2)->switch(m2.getName()){case "getHost"->host;case "getPort"->po;case "getProtocol"->ssl?"https":"http";default->defaultValue(m2);});}if(m.getName().equals("analyzeRequest")){IHttpService s=(IHttpService)a[0];String req=new String((byte[])a[1],StandardCharsets.ISO_8859_1);URL u=new URL(s.getProtocol(),s.getHost(),s.getPort(),req.split(" ",3)[1]);return proxy(IRequestInfo.class,(p2,m2,a2)->m2.getName().equals("getUrl")?u:defaultValue(m2));}return defaultValue(m);});
  IBurpExtenderCallbacks callbacks=proxy(IBurpExtenderCallbacks.class,(p,m,a)->{switch(m.getName()){case "getHelpers":return helpers;case "isInScope":scopeChecks.incrementAndGet();return true;case "addSuiteTab":tab.set(true);return null;case "makeHttpRequest":{sendCount.incrementAndGet();IHttpService s=(IHttpService)a[0];byte[] response=EngineTest.http(s.getHost(),s.getPort(),(byte[])a[1]);return proxy(IHttpRequestResponse.class,(p2,m2,a2)->m2.getName().equals("getResponse")?response:defaultValue(m2));}case "sendToRepeater":repeat.incrementAndGet();return null;}return defaultValue(m);});
  PayloadRunnerPanel ext=new PayloadRunnerPanel();ext.initializeEmbedded(callbacks,()->{});SwingUtilities.invokeAndWait(()->{});EngineTest.assertTest("embedded adapter provides panel without registering another suite tab",!tab.get()&&ext.getUiComponent()!=null);
  SwingUtilities.invokeAndWait(()->{ext.profile.setSelectedItem(Engine.Profile.XXE);EngineTest.assertTest("XXE profile switches RAW and XML instructions",ext.encoding.getSelectedItem()==Engine.Encoding.RAW&&ext.profileHint.getText().contains("XML")&&ext.payloads.getText().contains("<!ENTITY"));ext.profile.setSelectedItem(Engine.Profile.NOSQL);EngineTest.assertTest("NoSQL profile switches RAW and object instructions",ext.encoding.getSelectedItem()==Engine.Encoding.RAW&&ext.profileHint.getText().contains("JSON"));ext.profile.setSelectedItem(Engine.Profile.SSTI);EngineTest.assertTest("SSTI profile switches URL and evaluation presets",ext.encoding.getSelectedItem()==Engine.Encoding.URL&&ext.payloads.getText().contains("731*919"));ext.profile.setSelectedItem(Engine.Profile.XSS);});
  SwingUtilities.invokeAndWait(()->{ext.mode.setSelectedIndex(1);ext.port.setValue(port);ext.request.setText("GET /xss?q=§PAYLOAD§ HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n\r\n");ext.base.setText("alpha");ext.payloads.setText("<svg onload=console.log('{{MARKER}}')>");ext.interval.setValue(0);ext.startScan();});
  long end=System.currentTimeMillis()+10000;while(ext.running&&System.currentTimeMillis()<end)Thread.sleep(20);SwingUtilities.invokeAndWait(()->{});
  EngineTest.assertTest("Start sends baseline and chosen payload through Burp callback",sendCount.get()==2&&ext.model.getRowCount()==2&&scopeChecks.get()==3);EngineTest.assertTest("candidate evidence visible in result model",ext.model.getValueAt(1,5).equals("XSS 반사 후보"));
  SwingUtilities.invokeAndWait(()->{ext.table.setRowSelectionInterval(1,1);ext.repeater.doClick();});EngineTest.assertTest("selected tested request sent to Repeater",repeat.get()==1&&ext.detail.getText().contains("XSS 반사 후보"));
  String original="GET /xss?q=hello%20world HTTP/1.1\r\nHost: localhost\r\nCookie: training=dummy\r\nConnection: close\r\n\r\n";byte[] bytes=original.getBytes(StandardCharsets.ISO_8859_1);IHttpService service=helpers.buildHttpService("127.0.0.1",port,false);IHttpRequestResponse rr=proxy(IHttpRequestResponse.class,(p,m,a)->switch(m.getName()){case "getRequest"->bytes;case "getHttpService"->service;default->defaultValue(m);});int start=original.indexOf("hello");IContextMenuInvocation event=proxy(IContextMenuInvocation.class,(p,m,a)->switch(m.getName()){case "getSelectedMessages"->new IHttpRequestResponse[]{rr};case "getSelectionBounds"->new int[]{start,start+13};case "getInvocationContext"->IContextMenuInvocation.CONTEXT_MESSAGE_EDITOR_REQUEST;default->defaultValue(m);});
  var menus=ext.createMenuItems(event);SwingUtilities.invokeAndWait(()->menus.get(1).doClick());SwingUtilities.invokeAndWait(()->{});EngineTest.assertTest("context selection imports and marks captured request",ext.request.getText().contains("q=§PAYLOAD§")&&ext.base.getText().equals("hello world"));EngineTest.assertTest("captured cookie preserved",ext.request.getText().contains("Cookie: training=dummy"));
  EngineTest.assertTest("CSV formula cells neutralized",PayloadRunnerPanel.csvCell("=cmd()").equals("\"'=cmd()\""));ext.extensionUnloaded();EngineTest.assertTest("extension unload stops executor",ext.worker.isShutdown()&&ext.cancel.get());
 }
}
